def dashify(string: str) -> str:
    """Replace underscores with hyphens in the given string."""
    return string.replace("_", "-")

logger = logging.getLogger(__name__)

class GitError(Exception):
    """Base class for git-related errors."""
    pass

class UnsafeOptionError(GitError):
    """Exception raised for unsafe git options."""
    pass

class GitCommandError(GitError):
    """Exception raised for git command errors."""
    def __init__(self, call: List[str], exit_code: int, stderr: str):
        self.call = call
        self.exit_code = exit_code
        self.stderr = stderr
        super().__init__(f"Git command error: {call} (exit code: {exit_code})\n{stderr}")

class Git:
    """Manage communication with the Git binary.

    Example usage:

        g = Git(git_dir)
        g.init()  # Calls 'git init' program
        rval = g.ls_files()  # Calls 'git ls-files' program
    """

    __slots__ = (
        "_working_dir",
        "_git_options",
        "_persistent_git_options",
        "_environment",
    )

    git_exec_name = "git"
    GIT_PYTHON_TRACE = os.environ.get("GIT_PYTHON_TRACE", False)
    USE_SHELL: bool = False

    @classmethod
    def check_unsafe_options(cls, options: List[str], unsafe_options: List[str]) -> None:
        """Raise :class:`~git.exc.UnsafeOptionError` for blocked option spellings."""
        canonical_unsafe_options = {cls._canonicalize_option_name(option): option for option in unsafe_options}
        for option in options:
            candidate = cls._canonicalize_option_name(option)
            if candidate and candidate in canonical_unsafe_options:
                raise UnsafeOptionError(f"{canonical_unsafe_options[candidate]} is not allowed")

    @classmethod
    def _canonicalize_option_name(cls, option: str) -> str:
        """Return the option name used for unsafe-option checks."""
        return dashify(option.lstrip("-").split("=", 1)[0].split(None, 1)[0])

    def __getattr__(self, name: str) -> Callable:
        """Create a callable object for git commands."""
        return lambda *args, **kwargs: self._call_process(name, *args, **kwargs)

    def _call_process(
        self, method: str, *args: Any, **kwargs: Any
    ) -> Union[str, bytes, Tuple[int, Union[str, bytes], str]]:
        """Run a git command with the specified arguments and return the result."""
        method = dashify(method)
        call = [self.git_exec_name, method] + self._git_options + list(args)
        logger.debug("Calling git with: %s", call)
        return self.execute(call)

    def execute(
        self,
        call: List[str],
        **kwargs: Any,
    ) -> Union[str, bytes, Tuple[int, Union[str, bytes], str]]:
        """Execute the specified call and return the result."""
        try:
            process = subprocess.Popen(call, stdout=PIPE, stderr=PIPE, **kwargs)
            stdout, stderr = process.communicate()
            exit_code = process.returncode

            if exit_code != 0:
                raise GitCommandError(call, exit_code, stderr.decode())

            return stdout.decode()
        except Exception as e:
            logger.error("Error running git command: %s", e)
            raise e
